Industry: {{ $json['Industry'] }}
Website text: {{ $json.summaryInput }}

Based on the above, respond with exactly two lines:
Summary: (2 sentences on what this company does)
Pain Point: (1 sentence on their most likely current business challenge)

parameters.jsCode:
const items = $input.all();

return items.map(item => {

  const data = item.json;
  const companyName = $('Get Leads').item.json["Company Name"];

  // Get the AI output
  const rawText = (
    data.text ||
    data.output ||
    data.response ||
    data.summary ||
    data.content ||
    ''
  ).toString();

  // Focus primarily on the Pain Point section
  const painPointMatch = rawText.match(
    /Pain Point\s*:\s*([\s\S]*)/i
  );

  const painPoint = painPointMatch
    ? painPointMatch[1]
    : rawText;

  const text = painPoint.toLowerCase();

  // Default solution
  let solutionCategory = 'AI / General Business Automation';
  let recommendedSolution = 'AI-powered business process automation';
  let businessValue = 'Reduce manual effort and improve operational efficiency';
  let outreachAngle = 'Explore opportunities to identify repetitive processes that could benefit from intelligent automation';

  const categories = [

    {
      name: 'Revenue & Growth Automation',
      keywords: [
        'revenue',
        'monetization',
        'monetise',
        'monetize',
        'conversion',
        'customer acquisition',
        'growth',
        'retention',
        'engagement',
        'supplier acquisition',
        'attract suppliers',
        'sales growth',
        'business growth'
      ],
      solution: 'AI-powered revenue, growth and customer engagement automation',
      value: 'Improve customer conversion, engagement and revenue-generating processes',
      angle: 'Explore opportunities to use AI and automation to improve conversion, customer engagement and scalable revenue growth'
    },

    {
      name: 'Customer Support Automation',
      keywords: [
        'customer support',
        'customer service',
        'support tickets',
        'support queries',
        'customer queries',
        'complaints',
        'helpdesk',
        'ticket volume',
        'response time'
      ],
      solution: 'AI-powered customer support and query automation',
      value: 'Reduce repetitive support workload and improve response speed',
      angle: 'Explore opportunities to automate repetitive customer interactions while keeping human teams involved for complex cases'
    },

    {
      name: 'Lead & Sales Automation',
      keywords: [
        'lead generation',
        'lead qualification',
        'prospecting',
        'sales process',
        'sales pipeline',
        'sales team',
        'crm',
        'prospects',
        'sales representatives',
        'sales representatives spend',
        'manual prospecting'
      ],
      solution: 'AI-powered lead research, qualification and sales workflow automation',
      value: 'Reduce manual prospecting effort and help sales teams focus on higher-value opportunities',
      angle: 'Explore opportunities to automate lead research and qualification so the sales team can focus on promising prospects'
    },

    {
      name: 'Data & Reporting Automation',
      keywords: [
        'data processing',
        'data entry',
        'manual reporting',
        'reporting',
        'reports',
        'spreadsheet',
        'dashboard',
        'analytics',
        'data analysis',
        'manual analysis'
      ],
      solution: 'Automated data processing, analytics and reporting workflows',
      value: 'Reduce manual reporting effort and enable faster data-driven decisions',
      angle: 'Explore opportunities to automate recurring reporting and turn operational data into faster actionable insights'
    },

    {
      name: 'Document & Knowledge Automation',
      keywords: [
        'document processing',
        'document search',
        'searching documents',
        'knowledge management',
        'information retrieval',
        'manual document',
        'files',
        'records'
      ],
      solution: 'AI-powered document processing and knowledge retrieval',
      value: 'Reduce time spent searching and processing information',
      angle: 'Explore opportunities to make internal information easier to retrieve and process automatically'
    },

    {
      name: 'Operations & Workflow Automation',
      keywords: [
        'manual process',
        'manual work',
        'repetitive process',
        'repetitive task',
        'workflow',
        'operational inefficiency',
        'operations',
        'supply chain',
        'inventory',
        'logistics',
        'process automation'
      ],
      solution: 'Intelligent workflow and process automation',
      value: 'Reduce repetitive manual work and improve operational efficiency',
      angle: 'Explore opportunities to automate repetitive operational processes and free teams to focus on higher-value work'
    },

    {
      name: 'Marketing Automation & Analytics',
      keywords: [
        'marketing campaign',
        'marketing analytics',
        'campaign analysis',
        'customer insights',
        'digital marketing',
        'advertising',
        'marketing data',
        'campaign performance'
      ],
      solution: 'AI-powered marketing analytics and automation',
      value: 'Reduce manual analysis and improve the speed of marketing decision-making',
      angle: 'Explore opportunities to automate marketing analysis and generate more actionable customer insights'
    }
  ];

  let bestMatch = null;
  let highestScore = 0;

  for (const category of categories) {

    let score = 0;

    for (const keyword of category.keywords) {
      if (text.includes(keyword)) {
        score++;
      }
    }

    if (score > highestScore) {
      highestScore = score;
      bestMatch = category;
    }
  }

  if (bestMatch) {
    solutionCategory = bestMatch.name;
    recommendedSolution = bestMatch.solution;
    businessValue = bestMatch.value;
    outreachAngle = bestMatch.angle;
  }

  return {
    json: {
      ...data,
      "Company Name": companyName,

      painPoint,
      solutionCategory,
      recommendedSolution,
      businessValue,
      outreachAngle,
      matchedKeywords: highestScore
    }
  };

});
